code.css:
/* The details page: a pushed screen, not a sheet. */
.memory-details { padding-top: 146px; }
.memory-details__header { display: flex; flex-direction: column; gap: 4px; }
.memory-details__fields {
  border-radius: 20px;
  background: var(--bg-surface);
}
.memory-details__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 54px;
  padding: 0 16px;
}

/* Delete sits fixed at the foot, clear of the rows. */
.memory-details__delete { position: absolute; inset: auto 16px 16px; height: 54px; }

code.jsx:
// Four screens, one route: the list pushes the details page, the page opens an edit
// sheet per field, and delete is a dialog over the page.
//
//   Memory            → the grouped list
//   Viewing a memory  → category, memory, timestamp, source, fields
//   Editing a memory  → one field in a sheet, keyboard up, page behind the scrim
//   Deleting a memory → the confirmation over the page
//
// The rows are the same component in all four; what changes is what is over them.

code.swiftui:
// The details page is pushed, so it owns its own nav.
struct MemoryDetails: View {
  let memory: Memory

  var body: some View {
    VStack(alignment: .leading, spacing: 24) {
      VStack(alignment: .leading, spacing: 4) {
        Text(memory.category).font(.system(size: 14, weight: .medium))
        Text(memory.text).font(.system(size: 20, weight: .semibold))
        Text(memory.updated).font(.system(size: 12))
      }
      SourceChip(label: memory.source)
      VStack(spacing: 0) {
        ForEach(memory.fields) { FieldRow(field: $0) }
      }
      .background(RoundedRectangle(cornerRadius: 20).fill(.background))
    }
    .padding(.horizontal, 16)
    .navigationTitle("Memory details")
  }
}
